css:
/* ==========================================================================
   LIFE — PENDING DUES RECOVERY   ·  STYLE
   Paste into Web Page → "Style" field (or a <style> block).
   All selectors are scoped under #pdr-app so they won't clash with the portal.
   ========================================================================== */
#pdr-app{
  --g-deep:#0F5132; --g-mid:#1B7A4B; --g-soft:#E8F5EC; --g-softer:#F4FBF6;
  --g-line:#CDE7D6; --g-line2:#E4F1E9; --ink:#1B2B22; --ink2:#4A6357; --white:#fff;
  --amber:#8A6100; --amber-bg:#FFF7E3; --red:#8C2F20; --red-bg:#FDEDEA;
  --blue:#1B4F72; --blue-bg:#EAF2F8;
  margin:0; font-family:"Segoe UI",Arial,Helvetica,sans-serif;
  background:linear-gradient(180deg,#F7FCF9 0%,#EEF7F1 100%);
  color:var(--ink); font-size:12px; position:relative;
}
#pdr-app *{box-sizing:border-box}
.navbar{display:none;}
.pager{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:10px 4px;font-size:13px}
.pg-info{color:var(--ink2)}
.pg-btns{display:flex;gap:4px;flex-wrap:wrap}
.pg-b{padding:4px 9px;border:1px solid #ccc;background:#fff;border-radius:5px;cursor:pointer}
.pg-b.cur{background:#1a56db;color:#fff;border-color:#1a56db}
.pg-b:disabled{opacity:.4;cursor:default}
.pg-dots{color:var(--ink2)}
.pg-jump input{width:52px;padding:3px 5px;border:1px solid #ccc;border-radius:4px}
/* HEADER */
#pdr-app .pdr-hd{
  background:linear-gradient(135deg,var(--g-deep) 0%,var(--g-mid) 100%);
  color:#fff; padding:12px 18px; position:sticky; top:0; z-index:60;
  box-shadow:0 2px 10px rgba(15,81,50,.22);
}
#pdr-app .hd-row{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap}
#pdr-app .hd-title{font-size:16px;font-weight:700;letter-spacing:.4px}
#pdr-app .hd-sub{font-size:10.5px;opacity:.85;margin-top:2px}
#pdr-app .hd-mode{display:flex;align-items:center;gap:8px;font-size:11px}
#pdr-app .hd-mode select{font-size:11px;padding:5px 8px;border-radius:5px;border:1px solid #ffffff55;background:#ffffff18;color:#fff}
#pdr-app .hd-mode select option{color:#000}
#pdr-app .badge-live{background:#ffffff22;border:1px solid #ffffff55;padding:3px 8px;border-radius:20px;font-size:9.5px;letter-spacing:.5px;color:#CFF6DD}

/* WRAP / PANELS */
#pdr-app .wrap{padding:12px 14px 60px}
#pdr-app .panel{background:var(--white);border:1px solid var(--g-line);border-radius:8px;margin-bottom:12px;overflow:hidden}
#pdr-app .panel-hd{background:var(--g-soft);padding:8px 12px;font-weight:700;font-size:12px;color:var(--g-deep);
  display:flex;justify-content:space-between;align-items:center;cursor:pointer;user-select:none;border-bottom:1px solid var(--g-line)}
#pdr-app .panel-hd:hover{background:#DDEFE3}
#pdr-app .panel-hd .tog{font-size:11px;font-weight:600;color:var(--g-mid)}
#pdr-app .panel-bd{padding:10px 12px}
#pdr-app .panel.collapsed .panel-bd{display:none}

/* KPI */
#pdr-app .kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;margin-bottom:12px}
#pdr-app .kpi{background:#fff;border:1px solid var(--g-line);border-left:4px solid var(--g-mid);border-radius:7px;padding:8px 10px}
#pdr-app .kpi .k-lbl{font-size:9.5px;text-transform:uppercase;letter-spacing:.5px;color:var(--ink2);font-weight:600}
#pdr-app .kpi .k-val{font-size:17px;font-weight:700;color:var(--g-deep);margin-top:3px}
#pdr-app .kpi .k-note{font-size:9.5px;color:var(--ink2);margin-top:2px}
#pdr-app .kpi.amber{border-left-color:#C79100}#pdr-app .kpi.amber .k-val{color:var(--amber)}
#pdr-app .kpi.red{border-left-color:#B4432E}#pdr-app .kpi.red .k-val{color:var(--red)}
#pdr-app .kpi.blue{border-left-color:#2E6DA4}#pdr-app .kpi.blue .k-val{color:var(--blue)}

/* FILTERS */
#pdr-app .filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:8px}
#pdr-app .fld{display:flex;flex-direction:column;gap:3px}
#pdr-app .fld label{font-size:9.5px;font-weight:600;color:var(--ink2);text-transform:uppercase;letter-spacing:.4px}
#pdr-app .fld select,#pdr-app .fld input{font-size:11px;padding:5px 6px;border:1px solid var(--g-line);border-radius:5px;background:#fff;color:var(--ink)}
#pdr-app .fld select:focus,#pdr-app .fld input:focus{outline:2px solid #9FD6B4;outline-offset:0}

/* BUTTONS */
#pdr-app .btnbar{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}
#pdr-app button.b{font-size:11px;padding:6px 12px;border-radius:5px;border:1px solid var(--g-mid);background:var(--g-mid);color:#fff;cursor:pointer;font-weight:600}
#pdr-app button.b:hover{background:var(--g-deep);border-color:var(--g-deep)}
#pdr-app button.b.ghost{background:#fff;color:var(--g-deep)}
#pdr-app button.b.ghost:hover{background:var(--g-soft)}
#pdr-app button.b.warn{background:#fff;color:var(--red);border-color:#E0B4AA}
#pdr-app button.b.warn:hover{background:var(--red-bg)}

/* TABLE */
#pdr-app .tbl-scroll{overflow:auto;max-height:640px;border:1px solid var(--g-line2);border-radius:6px}
#pdr-app table{border-collapse:collapse;width:100%;font-size:11px;background:#fff}
#pdr-app th,#pdr-app td{border:1px solid var(--g-line2);padding:5px 6px;vertical-align:middle}
#pdr-app thead th{background:var(--g-soft);color:var(--g-deep);font-size:10px;text-transform:uppercase;letter-spacing:.3px;position:sticky;top:0;z-index:5;cursor:pointer;white-space:nowrap}
#pdr-app thead th.grp{background:var(--g-mid);color:#fff;text-align:center;cursor:default;top:0}
#pdr-app thead tr.r2 th{top:25px}
#pdr-app thead th:hover{background:#D7EEDF}
#pdr-app thead th.grp:hover{background:var(--g-mid)}
#pdr-app tbody tr:nth-child(even){background:var(--g-softer)}
#pdr-app tbody tr:hover{background:#E4F3EA}
#pdr-app td.num{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}
#pdr-app td.ctr{text-align:center}
#pdr-app .sub{display:block;font-size:9.5px;color:var(--ink2);margin-top:1px}
#pdr-app .code{font-family:Consolas,monospace;font-size:10px;background:var(--g-soft);border:1px solid var(--g-line);padding:1px 4px;border-radius:3px;color:var(--g-deep)}
#pdr-app .aging{font-size:9.5px;padding:1px 5px;border-radius:9px;display:inline-block;font-weight:600}
#pdr-app .a0{background:var(--g-soft);color:var(--g-deep)}
#pdr-app .a1{background:var(--amber-bg);color:var(--amber)}
#pdr-app .a2{background:var(--red-bg);color:var(--red)}

/* row status tint */
#pdr-app tr.st-COLLECTED{box-shadow:inset 3px 0 0 var(--g-mid)}
#pdr-app tr.st-COMMITTED{box-shadow:inset 3px 0 0 #2E6DA4}
#pdr-app tr.st-PARTIAL{box-shadow:inset 3px 0 0 #C79100}
#pdr-app tr.st-NOTCOLL{box-shadow:inset 3px 0 0 #B4432E}
#pdr-app tr.st-DISPUTE{box-shadow:inset 3px 0 0 #7B5EA7}
#pdr-app tr.err td{background:#FFF3F1 !important}
#pdr-app tr.saving td{background:#FFFBEA !important}

/* inline inputs */
#pdr-app .mi{font-size:10.5px;padding:3px 4px;border:1px solid var(--g-line);border-radius:4px;width:100%;background:#fff}
#pdr-app .mi:disabled{background:#F2F5F3;color:#AAB5AE;border-color:#E7EDE9}
#pdr-app select.mi{font-weight:600}
#pdr-app select.mi.v-COLLECTED{color:var(--g-deep)}
#pdr-app select.mi.v-COMMITTED{color:var(--blue)}
#pdr-app select.mi.v-PARTIAL{color:var(--amber)}
#pdr-app select.mi.v-NOTCOLL{color:var(--red)}
#pdr-app select.mi.v-PENDING{color:#8A968E}
#pdr-app .wc{font-size:9px;color:var(--ink2);text-align:right;margin-top:1px}
#pdr-app .wc.over{color:var(--red);font-weight:700}
#pdr-app .hint{font-size:9.5px;color:var(--ink2);margin-top:6px;line-height:1.5}

/* summary tables */
#pdr-app tfoot td,#pdr-app tr.tot td{background:var(--g-soft);font-weight:700;color:var(--g-deep)}
#pdr-app .legend{display:flex;gap:12px;flex-wrap:wrap;font-size:10px;color:var(--ink2);margin-top:8px}
#pdr-app .legend i{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:4px}

/* steps */
#pdr-app .steps{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:8px}
#pdr-app .step{background:var(--g-softer);border:1px solid var(--g-line);border-radius:6px;padding:8px 10px}
#pdr-app .step b{display:block;color:var(--g-deep);font-size:11px;margin-bottom:3px}
#pdr-app .step span{font-size:10px;color:var(--ink2);line-height:1.5}

/* toast + loader */
#pdr-app .toast{position:fixed;bottom:16px;right:16px;background:var(--g-deep);color:#fff;padding:9px 14px;border-radius:6px;font-size:11.5px;z-index:200;opacity:0;transform:translateY(8px);transition:.25s;box-shadow:0 4px 14px rgba(0,0,0,.2)}
#pdr-app .toast.show{opacity:1;transform:translateY(0)}
#pdr-app .toast.err{background:var(--red)}
#pdr-app .pdr-loader{position:fixed;inset:0;background:rgba(255,255,255,.72);display:none;align-items:center;justify-content:center;gap:12px;z-index:300;font-size:13px;color:var(--g-deep);font-weight:600}
#pdr-app .pdr-loader.show{display:flex}
#pdr-app .pdr-loader .spin{width:26px;height:26px;border:3px solid var(--g-line);border-top-color:var(--g-mid);border-radius:50%;animation:pdrspin .8s linear infinite}
@keyframes pdrspin{to{transform:rotate(360deg)}}
.web-footer{
    display :none;
}
@media print{
  #pdr-app .pdr-hd{position:static} #pdr-app .btnbar,#pdr-app .filters,#pdr-app .hd-mode{display:none}
  #pdr-app .tbl-scroll{max-height:none;overflow:visible}
  #pdr-app .pdr-loader{display:none !important}
}

/* =========================================================
   MAIN TABLE SORT BUTTONS
   ========================================================= */

#pdr-app .pdr-th-sort{
  display:flex;
  align-items:center;
  justify-content:center;
  gap:5px;
  white-space:nowrap;
}

#pdr-app .sort-btn{
  width:22px;
  height:22px;
  min-width:22px;
  padding:0;
  margin:0;

  display:inline-flex;
  align-items:center;
  justify-content:center;

  border:1px solid #BFD7C8;
  border-radius:5px;

  background:#FFFFFF;
  color:#527261;

  font-size:10px;
  line-height:1;

  cursor:pointer;

  transition:
    background .15s ease,
    border-color .15s ease,
    color .15s ease,
    box-shadow .15s ease;
}

#pdr-app .sort-btn:hover{
  background:#E8F5EC;
  border-color:#1B7A4B;
  color:#0F5132;
}

#pdr-app .sort-btn:focus{
  outline:none;
  border-color:#1B7A4B;
  box-shadow:0 0 0 2px rgba(27,122,75,.15);
}

#pdr-app .sort-ico{
  display:inline-block;
  font-size:10px;
  font-weight:700;
  line-height:1;
}

/* currently sorted column */
#pdr-app thead tr.r2 th.sort-active{
  background:#DDF1E4;
  color:#0F5132;
}

/* currently sorted button */
#pdr-app thead tr.r2 th.sort-active .sort-btn{
  background:#1B7A4B;
  border-color:#1B7A4B;
  color:#FFFFFF;
  box-shadow:0 1px 4px rgba(15,81,50,.20);
}

/* inactive sort buttons */
#pdr-app thead tr.r2 th:not(.sort-active) .sort-ico{
  color:#789487;
}
/* Pending Balances premium presentation — scoped to this module */
#pdr-app{--ink:#203a33;--ink2:#526b62;--g-line:#d8e5df;--g-soft:#eef5f1;--pdr-head-height:140px;background:#f2f6f4;font-size:13px;line-height:1.5;min-width:0}
#pdr-app .pdr-hd{background:linear-gradient(115deg,#153c31,#255e48);padding:17px clamp(14px,3vw,36px) 0;border-bottom:3px solid #c6a963;box-shadow:0 3px 15px #163e3024}
#pdr-app .hd-title{font-size:clamp(21px,2.1vw,29px);letter-spacing:-.6px;line-height:1.25;font-weight:750}
#pdr-app .pdr-brand{font-size:10px;letter-spacing:1.8px;color:#d2dbbd;font-weight:700;margin-bottom:4px}
#pdr-app .hd-sub{font-size:12px;opacity:1;color:#d3e4dc;margin-top:5px}
#pdr-app .hd-mode{flex-wrap:wrap;gap:7px;max-width:100%;font-size:12px}
#pdr-app .hd-mode select{background:#f5faf7;color:#244a39;border:1px solid #c2d7cb;font-size:12px;max-width:100%;min-height:34px;border-radius:7px}
#pdr-app .badge-live{font-size:10px;background:#ffffff12;color:#e1f5e7;white-space:nowrap}
#pdr-app .pdr-nav{display:flex;gap:5px;overflow-x:auto;margin-top:16px;padding-bottom:12px;scrollbar-width:thin;scrollbar-color:#b9cabe transparent}
#pdr-app .pdr-nav button{flex:0 0 auto;background:#ffffff0c;border:1px solid #ffffff18;border-radius:7px;padding:8px 12px;color:#e5f0e9;font-size:12px;font-weight:650;cursor:pointer}
#pdr-app .pdr-nav button:hover,#pdr-app .pdr-nav button[aria-current]{background:#f3f6eb;color:#214c39}
#pdr-app .pdr-nav .pdr-reset{margin-left:auto}
#pdr-app .wrap{padding:18px clamp(12px,2vw,30px) 60px;max-width:1900px;margin:auto;display:flex;flex-direction:column;gap:15px;min-width:0}
#pdr-app .panel{margin:0;min-width:0;border:1px solid #d7e3dc;border-top:3px solid var(--panel-accent,#579476);border-radius:12px;box-shadow:0 2px 5px #20463209;scroll-margin-top:calc(var(--pdr-head-height) + 16px)}
#pdr-app .panel-hd{padding:12px 15px;gap:10px;flex-wrap:wrap;background:linear-gradient(110deg,var(--panel-tint,#f1f7f3),#fff);color:#254335;cursor:default;min-height:57px;font-size:16px;line-height:1.35;border-color:#e0e9e3}
#pdr-app .panel-hd:hover{background:linear-gradient(110deg,var(--panel-tint,#f1f7f3),#fff)}
#pdr-app .pdr-section-caption{flex:1;min-width:180px}
#pdr-app .pdr-section-title{font-size:16px;display:block;font-weight:750;margin:0;line-height:1.35}
#pdr-app .pdr-section-sub{font-size:11px;display:block;color:#5b7368;font-weight:400;margin-top:3px}
#pdr-app .panel-hd .tog{font-size:11px;color:#557164;white-space:nowrap}
#pdr-app .pdr-panel-tools{display:flex;gap:5px;align-items:center;margin-left:auto}
#pdr-app .pdr-panel-tools button{border:1px solid #d4e0d8;background:#fff;color:#496457;padding:5px 8px;border-radius:6px;font-size:11px;min-height:29px;cursor:pointer;font-weight:600}
#pdr-app .pdr-panel-tools button:disabled{opacity:.35;cursor:default}
#pdr-app .panel-bd{padding:14px;min-width:0}
#pdr-app #pSchedule{--panel-accent:#b49a53;--panel-tint:#faf7eb}
#pdr-app #pOverview{--panel-accent:#568b74;--panel-tint:#edf7f1}
#pdr-app #pFilter{--panel-accent:#80958c;--panel-tint:#f1f4f2}
#pdr-app #pMain{--panel-accent:#5b8ca2;--panel-tint:#edf4f8}
#pdr-app #pClean{--panel-accent:#b49961;--panel-tint:#faf5e9}
#pdr-app #pBr{--panel-accent:#689b91;--panel-tint:#eef7f5}
#pdr-app #pEmp{--panel-accent:#9583ac;--panel-tint:#f5f0fa}
#pdr-app #pFlow{--panel-accent:#879ba6;--panel-tint:#f0f4f6}
#pdr-app .pdr-due-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
#pdr-app .pdr-due-card{min-width:0;border:1px solid #dae5de;border-radius:10px;overflow:hidden;background:#fff}
#pdr-app .pdr-due-top{display:flex;justify-content:space-between;gap:7px;padding:12px 14px;background:var(--due-tint);border-bottom:1px solid #e1e6df;color:var(--due-ink)}
#pdr-app .pdr-due-top h3{font-size:16px;line-height:1.3;margin:0;font-weight:750}
#pdr-app .pdr-due-top small{display:block;margin-top:4px;font-size:11px;color:#53675c}
#pdr-app .pdr-due-icon{font-size:12px;font-weight:750;background:#ffffffaa;border:1px solid #ffffff;border-radius:6px;align-self:flex-start;padding:3px 7px}
#pdr-app .pdr-due-scheduled{padding:14px;background:#fff}
#pdr-app .pdr-due-label{display:block;font-size:10px;text-transform:uppercase;letter-spacing:.5px;font-weight:700;color:#5e7568}
#pdr-app .pdr-due-value{display:block;font-size:clamp(23px,2vw,32px);font-weight:750;font-variant-numeric:tabular-nums;color:var(--due-ink);letter-spacing:-.6px;line-height:1.3;overflow-wrap:anywhere;margin:5px 0}
#pdr-app .pdr-due-count{font-size:11px;color:#5a7165;display:block}
#pdr-app .pdr-due-confirmed{padding:12px 14px;background:#eaf5f0;border-top:1px solid #d4e8de;display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}
#pdr-app .pdr-due-confirmed strong{font-size:clamp(18px,1.5vw,23px);color:#216648;font-variant-numeric:tabular-nums;overflow-wrap:anywhere}
#pdr-app .pdr-due-explain{margin:12px 0 0;font-size:11px;color:#526e61;line-height:1.6}
#pdr-app .kpis{grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin:0}
#pdr-app .kpi{border:1px solid #dbe5de;border-left:3px solid #508a6b;border-radius:8px;padding:12px;background:linear-gradient(140deg,#fff,#f3f8f5);min-width:0}
#pdr-app .kpi .k-lbl{font-size:10px;color:#536c5e;font-weight:700;line-height:1.5}
#pdr-app .kpi .k-val{font-size:clamp(19px,1.5vw,25px);letter-spacing:-.4px;overflow-wrap:anywhere;margin:6px 0 4px}
#pdr-app .kpi .k-note{font-size:11px;line-height:1.5}
#pdr-app .kpi.blue{background:linear-gradient(140deg,#fff,#edf4fc)}
#pdr-app .kpi.amber{background:linear-gradient(140deg,#fff,#fff7e4)}
#pdr-app .kpi.red{background:linear-gradient(140deg,#fff,#fff0ef)}
#pdr-app .filters{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}
#pdr-app .fld label{font-size:10px;color:#4e685b;line-height:1.5}
#pdr-app .fld select,#pdr-app .fld input{font-size:12px;padding:8px 10px;height:36px;min-width:0;width:100%;border-color:#ccdcd1;border-radius:6px}
#pdr-app button.b{font-size:12px;padding:8px 13px;border-radius:6px;min-height:35px}
#pdr-app .btnbar{gap:7px;margin-top:14px}
#pdr-app .hint{background:#f4f7f5;border:1px solid #e0e8e2;border-radius:6px;padding:9px 11px;font-size:11px;margin-top:12px;line-height:1.6}
#pdr-app .tbl-scroll{max-height:620px;max-width:100%;min-width:0;border-color:#dce7df;border-radius:8px;scrollbar-width:thin;scrollbar-color:#a2b9aa #f3f7f4}
#pdr-app table{table-layout:auto;font-size:12px;line-height:1.5;border-collapse:separate;border-spacing:0}
#pdr-app th,#pdr-app td{padding:10px 10px;border:0;border-right:1px solid #e2eae5;border-bottom:1px solid #e2eae5;vertical-align:middle}
#pdr-app thead th{font-size:10px;white-space:normal;font-weight:750;letter-spacing:.25px;background:#edf4f0;color:#385547;cursor:default}
#pdr-app thead th:hover{background:#edf4f0}
#pdr-app #mainTbl{min-width:2380px;width:100%}
#pdr-app #mainTbl thead th.grp{height:33px;padding:8px 10px;background:#315d4a;font-size:11px}
#pdr-app #mainTbl thead th.grp:nth-child(2){background:#355d7c}
#pdr-app #mainTbl thead tr.r2 th{top:33px;text-align:left;padding:10px 9px}
#pdr-app .pdr-th-sort{justify-content:space-between;gap:5px;white-space:normal;min-height:26px;line-height:1.4}
#pdr-app #mainTbl th:nth-child(1),#pdr-app #mainTbl td:nth-child(1){min-width:42px;width:42px}
#pdr-app #mainTbl tr.r2 th:nth-child(2),#pdr-app #mainTbl td:nth-child(2){min-width:125px}
#pdr-app #mainTbl tr.r2 th:nth-child(3),#pdr-app #mainTbl td:nth-child(3){min-width:175px}
