javascript:
(function () {
  "use strict";

  var API_DATA = "/api/method/dues_recovery_data";
  var API_SAVE = "/api/method/dues_recovery_save";
  var LOAD_LIMIT = 100000;      // effectively no cap on records loaded
  var PAGE_SIZE = 15;           // records per page

  var STATUS = [
    { v:"PENDING",   t:"- Not yet updated -" },
    { v:"COLLECTED", t:"Already collected (full)" },
    // { v:"PARTIAL",   t:"Part collected, balance promised" },
    { v:"COMMITTED", t:"Yes, this can be collected" },
    { v:"NOTCOLL",   t:"This will not be collectable" },
    { v:"DISPUTE",   t:"Client dispute / on hold" }
  ];
  var REASONS = ["Client not reachable / number invalid","Client refused to pay","Service discontinued by client",
    "Duplicate or wrong billing entry","Discount agreed but not adjusted","Refund / package cancelled case",
    "Client shifted city / not traceable","Legal or medical complaint case","Other (explain in remark)"];
  var MODES = ["Cash","UPI","Card","Bank transfer","Cheque"];

  var FIELDS = {
    PENDING  :{col:0,mode:0,cmt:0,rsn:0,rmk:0},
    COLLECTED:{col:1,mode:1,cmt:0,rsn:0,rmk:1},
    PARTIAL  :{col:1,mode:1,cmt:1,rsn:0,rmk:1},
    COMMITTED:{col:0,mode:0,cmt:1,rsn:0,rmk:1},
    NOTCOLL  :{col:0,mode:0,cmt:0,rsn:1,rmk:1},
    DISPUTE  :{col:0,mode:0,cmt:0,rsn:0,rmk:1}
  };

  var ROWS = [];
  var BRANCHES = [];
  var MODE = "HO";

  // ERP columns that can also be sent to the server.
  var SERVER_SORTABLE = {
    branch: 1,
    client: 1,
    emp: 1,
    inv: 1,
    invAmt: 1,
    paid: 1,
    due: 1,
    nextDue: 1
  };

  // Every REAL table data column is sortable.
  // "#" is intentionally excluded because it is a generated serial number.
  var ALL_SORTABLE = {
    branch: 1,
    client: 1,
    emp: 1,
    inv: 1,
    invAmt: 1,
    paid: 1,
    due: 1,
    nextDue: 1,
    st: 1,
    colAmt: 1,
    colDate: 1,
    mode: 1,
    cmtAmt: 1,
    cmtDate: 1,
    reasonRemark: 1
  };

  // These manager-update columns sort primarily by VALUE AVAILABILITY.
  // desc = filled rows first
  // asc  = blank/unavailable rows first
  var AVAILABILITY_SORT = {
    st: 1,
    colAmt: 1,
    colDate: 1,
    mode: 1,
    cmtAmt: 1,
    cmtDate: 1,
    reasonRemark: 1
  };

  // Preserve existing default: highest due first.
  var sortKey = "due";
  var sortDir = "desc";

  var saveTimers = {};
  var PAGE = 1;                 // current page
  var CUR = [];                 // current filtered dataset (server order preserved)

  function $(id){ return document.getElementById(id); }
  function esc(s){
    s = (s==null?"":String(s));
    return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
  }
  function moneyNumber(v){var n=Number(String(v==null?"":v).replace(/[₹,\s]/g,""));return Number.isFinite(n)?n:0;}
  function todayISO(){var d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");}
  function inr(n){if(n===""||n===null||n===undefined)return "";return "₹"+moneyNumber(n).toLocaleString("en-IN",{maximumFractionDigits:2});}
  function ageCls(d){ return d<=30?"a0":(d<=90?"a1":"a2"); }
  function ageTxt(d){ return d<=0?"Not yet due":d+" days over"; }

  // Display ERP dates as 12-Aug-26 without changing the underlying value.
  function formatDateDisplay(v){
    if(v===null || v===undefined || String(v).trim()==="") return "";

    var s=String(v).trim();
    var y, m, d;

    // yyyy-mm-dd or yyyy-mm-dd HH:mm:ss
    var a=s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
    if(a){
      y=parseInt(a[1],10);
      m=parseInt(a[2],10);
      d=parseInt(a[3],10);
    }else{
      // dd-mm-yyyy or dd/mm/yyyy
      var b=s.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
      if(b){
        d=parseInt(b[1],10);
        m=parseInt(b[2],10);
        y=parseInt(b[3],10);
      }else{
        var dt=new Date(s);
        if(isNaN(dt.getTime())) return s;
        y=dt.getFullYear();
        m=dt.getMonth()+1;
        d=dt.getDate();
      }
    }

    var mons=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    if(m<1 || m>12 || d<1 || d>31) return s;

    return String(d).padStart(2,"0")+"-"+mons[m-1]+"-"+String(y).slice(-2);
  }
  function words(s){ return String(s||"").trim().split(/\s+/).filter(Boolean); }
  function toast(m,err){ var t=$("toast"); t.textContent=m; t.className="toast show"+(err?" err":""); clearTimeout(t._t); t._t=setTimeout(function(){t.classList.remove("show");},2600); }
  function loader(on){ $("loader").classList.toggle("show",!!on); }
  function opt(v,t){ var o=document.createElement("option"); o.value=v; o.textContent=t; return o; }
  function tog(id){ $(id).classList.toggle("collapsed"); }
  function getCSRF(){ return (window.frappe&&frappe.csrf_token)||(window.csrf_token)||""; }
  function cssId(s){ return String(s).replace(/[^A-Za-z0-9_-]/g,"_"); }

  // ---- mobile masking ----
  function maskMobile(s){
    s = String(s==null?"":s).trim();
    if(!s) return "";
    var digits = s.replace(/\D/g,"");
    if(digits.length < 4) return s.replace(/./g,"X");
    var last4 = digits.slice(-4);
    return "XXXXXX" + last4;
  }

  function initStaticFilters(){
    var s=$("fStatus"); s.innerHTML=""; s.appendChild(opt("","All statuses"));
    STATUS.forEach(function(x){ s.appendChild(opt(x.v, x.t.replace(/-/g,"").trim())); });
  }
  function fillBranchDropdowns(){
    var b=$("fBranch"); var cur=b.value; b.innerHTML=""; b.appendChild(opt("","All branches"));
    var bl=$("brLock"); bl.innerHTML="";
    BRANCHES.forEach(function(x){
      b.appendChild(opt(x.branch, x.branch+"  ("+x.n+")"));
      bl.appendChild(opt(x.branch, x.branch));
    });
    if(cur)b.value=cur;
  }
  function fillEmp(){
    var e=$("fEmp"); var cur=e.value; e.innerHTML=""; e.appendChild(opt("","All employees"));
    var seen={}, list=[];
    ROWS.forEach(function(r){ if(r.emp && !seen[r.emp]){ seen[r.emp]=1; list.push(r.emp); } });
    list.sort();
    list.forEach(function(x){ e.appendChild(opt(x,x)); });
    if(seen[cur])e.value=cur;
  }
  function activeBranch(){ return MODE==="BR" ? $("brLock").value : $("fBranch").value; }
  function setMode(){
    MODE=$("modeSel").value;
    var bl=$("brLock");
    if(MODE==="BR"){ bl.style.display=""; $("fBranch").value=bl.value; }
    else { bl.style.display="none"; }
    reload();
  }
  function clearFilters(){
    ["fBranch","fEmp","fStatus","fAge","fFrom","fTo","fMin","fSearch"].forEach(function(id){ $(id).value=""; });
    reload();
  }

  function reload(){
    loader(true);
    var p=new URLSearchParams();
    var br=activeBranch();
    if(br)p.set("branch",br);
    if($("fFrom").value)p.set("from",$("fFrom").value);
    if($("fTo").value)p.set("to",$("fTo").value);
    if($("fMin").value)p.set("min_due",$("fMin").value);
    if($("fSearch").value.trim())p.set("q",$("fSearch").value.trim());

    // Ask the server to return rows in the selected order.
    if(SERVER_SORTABLE[sortKey]){
      p.set("sort_by", sortKey);
      p.set("sort_dir", sortDir);
    }

    p.set("limit",LOAD_LIMIT);
    fetch(API_DATA+"?"+p.toString(),{headers:{"X-Frappe-CSRF-Token":getCSRF()}})
      .then(function(res){ return res.json(); })
      .then(function(j){
        var m=j.message||{};
        ROWS=(m.rows||[]).map(function(r){["invAmt","paid","due"].forEach(function(k){r[k]=moneyNumber(r[k]);});["colAmt","cmtAmt"].forEach(function(k){if(r[k]!==""&&r[k]!==null&&r[k]!==undefined)r[k]=String(moneyNumber(r[k]));});return r;});
        enrichClients(ROWS);
        BRANCHES=m.branches||[];
        fillBranchDropdowns();
        if(MODE==="BR")$("fBranch").value=$("brLock").value;
        else if(br)$("fBranch").value=br;
        fillEmp();
        PAGE=1;
        applyFilters();
        toast(ROWS.length+" invoices loaded live");
      })
      .catch(function(e){ toast("Could not load live data. Check the APIs are installed.",1); void 0; })
      .then(function(){ loader(false); });
  }

  function filtered(){
    var emp=$("fEmp").value, st=$("fStatus").value, ag=$("fAge").value;
    return ROWS.filter(function(r){
      if(emp&&r.emp!==emp)return false;
      if(st&&r.st!==st)return false;
      if(ag!==""){ var b=r.age<=30?0:(r.age<=90?1:2); if(String(b)!==ag)return false; }
      return true;
    });
  }
  function sortBy(k){
    if(!ALL_SORTABLE[k]) return;

    if(sortKey===k){
      sortDir = sortDir==="asc" ? "desc" : "asc";
    }else{
      sortKey = k;

      // Amount/date ERP columns start highest/latest first.
      // Manager-update availability columns start with FILLED rows first.
      sortDir = (
        k==="inv" ||
        k==="invAmt" ||
        k==="paid" ||
        k==="due" ||
        k==="nextDue" ||
        AVAILABILITY_SORT[k]
      ) ? "desc" : "asc";
    }

    PAGE=1;
    updateSortIndicators();

    // ERP fields may also be sorted by the server.
    // Manager-update fields are globally sorted in the complete loaded dataset.
    if(SERVER_SORTABLE[k]){
      reload();
    }else{
      applyFilters();
    }
  }

  function updateSortIndicators(){
    var ths=document.querySelectorAll("#mainTbl thead tr.r2 th[data-sort-key]");
    for(var i=0;i<ths.length;i++){
      var th=ths[i];
      var key=th.getAttribute("data-sort-key");
      var ico=th.querySelector(".sort-ico");
      th.classList.toggle("sort-active", key===sortKey);
      th.setAttribute("aria-sort",key===sortKey?(sortDir==="asc"?"ascending":"descending"):"none");
      if(ico){
        ico.textContent = key===sortKey ? (sortDir==="asc" ? " ▲" : " ▼") : " ↕";
      }
    }
  }

  function hasSortValue(r,k){
    if(!r)return false;

    // PENDING means the manager has not provided a status update yet.
    if(k==="st"){
      return !!(r.st && r.st!=="PENDING");
    }

    // Amount fields: zero/blank is treated as no usable value.
    if(k==="colAmt" || k==="cmtAmt"){
      var n=parseFloat(r[k]);
      return !isNaN(n) && n>0;
    }

    if(k==="reasonRemark"){
      return !!(
        String(r.reason||"").trim() ||
        String(r.remark||"").trim()
      );
    }

    return !(
      r[k]===null ||
      r[k]===undefined ||
      String(r[k]).trim()===""
    );
  }

  function parseSortDate(v){
    if(!v)return 0;

    var t=Date.parse(v);
    if(!isNaN(t))return t;

    // dd-mm-yyyy or dd/mm/yyyy
    var m=String(v).match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
    if(m){
      return new Date(
        parseInt(m[3],10),
        parseInt(m[2],10)-1,
        parseInt(m[1],10)
      ).getTime();
    }

    return 0;
  }

  function sortValue(r,k){
    if(!r)return "";

    if(k==="invAmt" || k==="paid" || k==="due" ||
       k==="colAmt" || k==="cmtAmt"){
      var n=parseFloat(r[k]);
      return isNaN(n) ? 0 : n;
    }

    // IMPORTANT:
    // Invoice number uses natural string ordering.
    if(k==="inv"){
      return String(r.inv||"").toLowerCase();
    }

    if(k==="nextDue" || k==="colDate" || k==="cmtDate"){
      return parseSortDate(r[k]);
    }

    if(k==="reasonRemark"){
      return (
        String(r.reason||"").trim() + " " +
        String(r.remark||"").trim()
      ).trim().toLowerCase();
    }

    if(k==="st"){
      // Use the displayed status order as a stable secondary sort.
      var statusOrder = {
        PENDING:0,
        COLLECTED:1,
        COMMITTED:2,
        PARTIAL:3,
        NOTCOLL:4,
        DISPUTE:5
      };
      return statusOrder[r.st]===undefined ? 99 : statusOrder[r.st];
    }

    return String(r[k]==null?"":r[k]).trim().toLowerCase();
  }

  function compareSortValues(x,y){
    if(typeof x==="number" && typeof y==="number"){
      return x-y;
    }

    return String(x).localeCompare(
      String(y),
      undefined,
      {numeric:true,sensitivity:"base"}
    );
  }

  function globalSortRows(d){
    if(!ALL_SORTABLE[sortKey])return d;

    d.sort(function(a,b){
      var c=0;

      // Manager columns: VALUE AVAILABILITY is the primary sorting rule.
      if(AVAILABILITY_SORT[sortKey]){
        var av=hasSortValue(a,sortKey) ? 1 : 0;
        var bv=hasSortValue(b,sortKey) ? 1 : 0;

        if(av!==bv){
          // DESC = filled first. ASC = blank first.
          return sortDir==="desc" ? (bv-av) : (av-bv);
        }
      }

      // If both rows are filled (or both blank), compare their actual values.
      var x=sortValue(a,sortKey);
      var y=sortValue(b,sortKey);
      c=compareSortValues(x,y);

      // Stable deterministic tie-breaker keeps page boundaries consistent.
      if(c===0){
        c=String(a.inv||"").localeCompare(
          String(b.inv||""),
          undefined,
          {numeric:true,sensitivity:"base"}
        );
      }

      return sortDir==="asc" ? c : -c;
    });

    // Serial number belongs to the FULL globally-sorted result.
    for(var i=0;i<d.length;i++){
      d[i].sno=i+1;
    }

    return d;
  }

  function applyFilters(){
    // ONE ordering for the complete filtered table.
    // Sorting MUST happen before pagination.
    var d=globalSortRows(filtered().slice());

    CUR=d;

    var tp=Math.max(1,Math.ceil(d.length/PAGE_SIZE));
    if(PAGE>tp)PAGE=tp;
    if(PAGE<1)PAGE=1;

    // Only after the complete table has been sorted do we take a page.
    var start=(PAGE-1)*PAGE_SIZE;
    var pageRows=d.slice(start,start+PAGE_SIZE);

    renderTable(pageRows,d);
    renderKPI(d);
    renderClean(d);
    renderBranch(d);
    renderEmp(d);
    renderCollections(d);
    renderPager(d);
    updateSortIndicators();

    $("cntTag").textContent=d.length+" invoices  \u25BE";
  }

  function gotoPage(p){
    var tp=Math.max(1,Math.ceil(CUR.length/PAGE_SIZE));
    if(p<1)p=1; if(p>tp)p=tp;
    PAGE=p;
    applyFilters();
    var g=$("gridWrap"); if(g)g.scrollTop=0;
    window.scrollTo(0,0);
  }

  function renderPager(d){
    var el=$("pager");
    if(!el)return;
    var tp=Math.max(1,Math.ceil(d.length/PAGE_SIZE));
    var start=d.length?((PAGE-1)*PAGE_SIZE+1):0;
    var end=Math.min(PAGE*PAGE_SIZE,d.length);
    var h="";
    h += "<span class=\"pg-info\">Showing "+start+"-"+end+" of "+d.length+"</span>";
    h += "<span class=\"pg-btns\">";
    h += "<button class=\"pg-b\""+(PAGE<=1?" disabled":"")+" onclick=\"PDR.page(1)\">&laquo; First</button>";
    h += "<button class=\"pg-b\""+(PAGE<=1?" disabled":"")+" onclick=\"PDR.page("+(PAGE-1)+")\">&lsaquo; Prev</button>";

    var from=Math.max(1,PAGE-2), to=Math.min(tp,PAGE+2);
    if(from>1)h += "<span class=\"pg-dots\">...</span>";
    for(var i=from;i<=to;i++){
      h += "<button class=\"pg-b"+(i===PAGE?" cur":"")+"\" onclick=\"PDR.page("+i+")\">"+i+"</button>";
    }
    if(to<tp)h += "<span class=\"pg-dots\">...</span>";

    h += "<button class=\"pg-b\""+(PAGE>=tp?" disabled":"")+" onclick=\"PDR.page("+(PAGE+1)+")\">Next &rsaquo;</button>";
    h += "<button class=\"pg-b\""+(PAGE>=tp?" disabled":"")+" onclick=\"PDR.page("+tp+")\">Last &raquo;</button>";
    h += "</span>";
    h += "<span class=\"pg-jump\">Page <input id=\"pgInput\" type=\"number\" min=\"1\" max=\""+tp+"\" value=\""+PAGE+"\" onchange=\"PDR.page(parseInt(this.value,10)||1)\"> / "+tp+"</span>";
    el.innerHTML=h;
  }

  function optionsHTML(list, sel, useVal){
    var h="";
    for(var i=0;i<list.length;i++){
      var it=list[i];
      var val = useVal ? it.v : it;
      var lbl = useVal ? it.t : it;
      h += "<option value=\""+esc(val)+"\""+(val===sel?" selected":"")+">"+esc(lbl)+"</option>";
    }
    return h;
