      var disMode= F.mode?"":" disabled";
      var disCmt = F.cmt?"":" disabled";
      var disRmk = F.rmk?"":" disabled";

      h += "<tr class=\""+cls+"\" data-i=\""+esc(r.inv)+"\">";
      h += "<td class=\"ctr\">"+r.sno+"</td>";
      h += "<td><span class=\"code\">"+esc(r.branch)+"</span></td>";
      h += "<td>"+clientCell(r)+"</td>";
      h += "<td>"+esc(r.emp||"-")+"<span class=\"sub\">"+esc(r.practitioner||"")+"</span></td>";
      h += "<td><span class=\"code\">"+esc(r.inv)+"</span><span class=\"sub\">"+esc(formatDateDisplay(r.invDate))+" \u00B7 "+esc(r.service||"")+"</span></td>";
      h += "<td class=\"num\">"+inr(r.invAmt)+"</td>";
      h += "<td class=\"num\">"+inr(r.paid)+"</td>";
      h += "<td class=\"num\"><b>"+inr(r.due)+"</b></td>";
      h += "<td class=\"ctr\">"+esc(formatDateDisplay(r.nextDue))+"<span class=\"sub\"><span class=\"aging "+ageCls(r.age)+"\">"+ageTxt(r.age)+"</span></span></td>";

      h += "<td><select class=\"mi v-"+r.st+"\" onchange=\"PDR.setF('"+esc(r.inv)+"','st',this.value)\">"+optionsHTML(STATUS,r.st,true)+"</select></td>";

      h += "<td><input class=\"mi\" type=\"text\" inputmode=\"decimal\" onblur=\"PDR.formatAmount(this)\" min=\"0\" max=\""+r.due+"\" placeholder=\"0\" value=\""+esc(r.colAmt?inr(r.colAmt):"")+"\""+disCol+" onchange=\"PDR.setF('"+esc(r.inv)+"','colAmt',this.value)\"></td>";

      h += "<td><input class=\"mi\" type=\"date\" min=\""+todayISO()+"\" value=\""+esc(r.colDate)+"\""+disCol+" onchange=\"PDR.setF('"+esc(r.inv)+"','colDate',this.value)\"></td>";

      h += "<td><select class=\"mi\""+disMode+" onchange=\"PDR.setF('"+esc(r.inv)+"','mode',this.value)\"><option value=\"\">-</option>"+optionsHTML(MODES,r.mode,false)+"</select></td>";

      h += "<td><input class=\"mi\" type=\"text\" inputmode=\"decimal\" onblur=\"PDR.formatAmount(this)\" min=\"0\" max=\""+r.due+"\" placeholder=\"0\" value=\""+esc(r.cmtAmt?inr(r.cmtAmt):"")+"\""+disCmt+" onchange=\"PDR.setF('"+esc(r.inv)+"','cmtAmt',this.value)\"></td>";

      h += "<td><input class=\"mi\" type=\"date\" min=\""+todayISO()+"\" value=\""+esc(r.cmtDate)+"\""+disCmt+" onchange=\"PDR.setF('"+esc(r.inv)+"','cmtDate',this.value)\"></td>";

      h += "<td>";
      if(F.rsn){
        h += "<select class=\"mi\" style=\"margin-bottom:3px\" onchange=\"PDR.setF('"+esc(r.inv)+"','reason',this.value)\"><option value=\"\">- select reason -</option>"+optionsHTML(REASONS,r.reason,false)+"</select>";
      }
      var ph = F.rmk?"Manager remark (max 25 words)":"-";
      h += "<textarea class=\"mi\" rows=\"2\" placeholder=\""+ph+"\""+disRmk+" onchange=\"PDR.setRemark('"+esc(r.inv)+"',this)\" oninput=\"PDR.wc('"+esc(r.inv)+"',this)\">"+esc(r.remark||"")+"</textarea>";
      h += "<div class=\"wc\" id=\"wc_"+cssId(r.inv)+"\">"+words(r.remark).length+"/25 words</div>";
      h += "</td>";
      h += "</tr>";
    }
    tb.innerHTML = h || "<tr><td colspan=\"16\" style=\"text-align:center;padding:22px;color:var(--ink2)\">No invoices match these filters. Clear a filter or hit Refresh.</td></tr>";

    // footer totals across the FULL filtered set (not just this page)
    var src = full || d;
    var ti=0,tp=0,td=0;
    for(var k=0;k<src.length;k++){ ti+=src[k].invAmt; tp+=src[k].paid; td+=src[k].due; }
    $("tf").innerHTML =
      "<td colspan=\"5\" style=\"text-align:right\">TOTAL - "+src.length+" invoices (all pages)</td>"+
      "<td class=\"num\">"+inr(ti)+"</td><td class=\"num\">"+inr(tp)+"</td><td class=\"num\">"+inr(td)+"</td>"+
      "<td colspan=\"8\"></td>";
  }

  function calc(d){
    var gross=0,collected=0,committed=0,writeoff=0,dispute=0,pending=0,doneRows=0;
    for(var i=0;i<d.length;i++){
      var r=d[i];
      gross+=r.due;
      var c=parseFloat(r.colAmt)||0, m=parseFloat(r.cmtAmt)||0;
      if(r.st==="COLLECTED"){ collected+=c||r.due; }
      else if(r.st==="PARTIAL"){ collected+=c; committed+=m; }
      else if(r.st==="COMMITTED"){ committed+=m; }
      else if(r.st==="NOTCOLL"){ writeoff+=r.due; }
      else if(r.st==="DISPUTE"){ dispute+=r.due; }
      else pending+=r.due;
      if(r.st!=="PENDING")doneRows++;
    }
    var real=gross-collected-writeoff;
    return {gross:gross,collected:collected,committed:committed,writeoff:writeoff,dispute:dispute,pending:pending,real:real,doneRows:doneRows,n:d.length};
  }

  function kpi(cls,lbl,val,note){
    return "<div class=\"kpi "+cls+"\"><div class=\"k-lbl\">"+lbl+"</div><div class=\"k-val\">"+val+"</div><div class=\"k-note\">"+note+"</div></div>";
  }
  function renderKPI(d){
    if(window.PDRPremium)window.PDRPremium.renderDue(d);
    var c=calc(d); var pct=c.n?Math.round(c.doneRows/c.n*100):0;
    $("kpis").innerHTML =
      kpi("","Gross pending due",inr(c.gross),c.n+" invoices in view")+
      kpi("blue","Update completed",pct+"%",c.doneRows+" of "+c.n+" rows updated")+
      kpi("","Collected now",inr(c.collected),"receipted against these invoices")+
      kpi("amber","Committed by client",inr(c.committed),"promised with a date")+
      kpi("red","Proposed for removal",inr(c.writeoff),"needs HO approval")+
      kpi("","Real balance left",inr(c.real),"after collection &amp; clean-up");
  }
  function renderClean(d){
    var c=calc(d);
    function row(l,v,b){ return "<tr"+(b?" class=\"tot\"":"")+"><td>"+l+"</td><td class=\"num\">"+inr(v)+"</td></tr>"; }
    $("cleanTbl").innerHTML =
      "<thead><tr><th>Particulars</th><th style=\"text-align:right;width:150px\">Amount</th></tr></thead><tbody>"+
      row("Gross pending due as per ERP",c.gross)+
      row("Less: collected during this drive",-c.collected)+
      row("Less: not collectable - proposed removal",-c.writeoff)+
      row("Real balance to be carried forward",c.real,1)+
      "<tr><td colspan=\"2\" style=\"height:6px;border:0\"></td></tr>"+
      row("  of which - committed with a date",c.committed)+
      row("  of which - disputed / on hold",c.dispute)+
      row("  of which - not yet updated by branch",c.pending)+
      "</tbody>";
  }
  function groupTbl(d,keyFn,labelFn,head){
    var m={}, order=[];
    for(var i=0;i<d.length;i++){ var k=keyFn(d[i]); if(!m[k]){m[k]=[];order.push(k);} m[k].push(d[i]); }
    order.sort(function(a,b){ return calc(m[b]).gross-calc(m[a]).gross; });
    var tot={gross:0,collected:0,committed:0,writeoff:0,real:0,n:0};
    var body="";
    for(var j=0;j<order.length;j++){
      var g=m[order[j]]; var c=calc(g);
      tot.gross+=c.gross; tot.collected+=c.collected; tot.committed+=c.committed; tot.writeoff+=c.writeoff; tot.real+=c.real; tot.n+=c.n;
      var pct=c.n?Math.round(c.doneRows/c.n*100):0;
      body += "<tr><td>"+labelFn(g[0])+"</td><td class=\"num\">"+c.n+"</td>"+
        "<td class=\"num\">"+inr(c.gross)+"</td><td class=\"num\">"+inr(c.collected)+"</td>"+
        "<td class=\"num\">"+inr(c.committed)+"</td><td class=\"num\">"+inr(c.writeoff)+"</td>"+
        "<td class=\"num\"><b>"+inr(c.real)+"</b></td><td class=\"ctr\">"+pct+"%</td></tr>";
    }
    if(!body)body="<tr><td colspan=\"8\" style=\"text-align:center;padding:16px;color:var(--ink2)\">Nothing to show.</td></tr>";
    return "<thead><tr><th>"+head+"</th><th>Invoices</th><th>Gross due</th><th>Collected</th>"+
      "<th>Committed</th><th>To remove</th><th>Real balance</th><th>Updated</th></tr></thead>"+
      "<tbody>"+body+"</tbody>"+
      "<tfoot><tr><td>TOTAL</td><td class=\"num\">"+tot.n+"</td><td class=\"num\">"+inr(tot.gross)+"</td>"+
      "<td class=\"num\">"+inr(tot.collected)+"</td><td class=\"num\">"+inr(tot.committed)+"</td>"+
      "<td class=\"num\">"+inr(tot.writeoff)+"</td><td class=\"num\">"+inr(tot.real)+"</td><td></td></tr></tfoot>";
  }
  function renderBranch(d){
    $("brTbl").innerHTML=groupTbl(d,function(r){return r.branch;},function(r){return "<span class=\"code\">"+esc(r.branch)+"</span>";},"Branch");
  }
  function renderEmp(d){
    $("empTbl").innerHTML=groupTbl(d,function(r){return r.emp+"|"+r.branch;},function(r){return esc(r.emp||"-")+"<span class=\"sub\">"+esc(r.branch)+"</span>";},"Booked by");
  }

  function setF(inv,k,v){
    var r=null;
    for(var i=0;i<ROWS.length;i++){ if(ROWS[i].inv===inv){ r=ROWS[i]; break; } }
    if(!r)return;
    if((k==="colAmt"||k==="cmtAmt")&&v!==""){
      var cleaned=String(v).replace(/[₹,\s]/g,"");
      if(!/^\d+(?:\.\d{1,2})?$/.test(cleaned)){toast("Enter a valid positive rupee amount (up to 2 decimals).",1);applyFilters();return;}
      var n=Number(cleaned);
      if(n>r.due){toast("Amount cannot exceed "+inr(r.due),1);applyFilters();return;}
      v=String(n);
    }
    if((k==="colDate"||k==="cmtDate")&&v){if(!validDate(v)||v<todayISO()||(k==="colDate"&&v>todayISO())){toast(k==="colDate"?"Collected date must be today.":"Promise date must be today or later.",1);applyFilters();return;}}
    r[k]=v;
    if(k==="st"){
      var F=FIELDS[v]||FIELDS.PENDING;
      if(!F.col){ r.colAmt=""; r.colDate=""; r.mode=""; }
      if(!F.cmt){ r.cmtAmt=""; r.cmtDate=""; }
      if(!F.rsn)r.reason="";
      if(v==="COLLECTED")r.colAmt=String(r.due);
      if(v==="COMMITTED"&&!r.cmtAmt)r.cmtAmt=String(r.due);
      applyFilters();
      save(r);
      return;
    }
    renderKPI(filtered()); renderClean(filtered()); renderBranch(filtered()); renderEmp(filtered());renderCollections(filtered());
    save(r);
  }
  function setRemark(inv,el){
    var r=null;
    for(var i=0;i<ROWS.length;i++){ if(ROWS[i].inv===inv){ r=ROWS[i]; break; } }
    if(!r)return;
    var w=words(el.value);
    if(w.length>25){ w=w.slice(0,25); el.value=w.join(" ")+" "; toast("Remark limit is 25 words."); }
    r.remark=el.value; wc(inv,el); save(r);
  }
  function wc(inv,el){
    var w=words(el.value).length;
    var box=$("wc_"+cssId(inv));
    if(box){ box.textContent=w+"/25 words"; box.classList.toggle("over",w>=25); }
  }

  function save(r){
    var tr=document.querySelector("#tb tr[data-i=\""+r.inv+"\"]");
    if(tr)tr.classList.add("saving");
    clearTimeout(saveTimers[r.inv]);
    saveTimers[r.inv]=setTimeout(function(){ doSave(r,tr); },400);
  }
  function doSave(r,tr){
    var error=validationError(r);if(error){if(tr){tr.classList.remove("saving");tr.classList.add("err");}toast(error+" · update not saved",1);return;}
    if(tr)tr.classList.remove("err");
    var body=new URLSearchParams({
      invoice_no:r.inv, branch:r.branch, manager_status:r.st,
      collected_amount:r.colAmt||0, collected_on:r.colDate||"",
      mode_of_payment:r.mode||"", committed_amount:r.cmtAmt||0,
      committed_by:r.cmtDate||"", reason:r.reason||"", remark:r.remark||""
    });
    fetch(API_SAVE,{
      method:"POST",
      headers:{"Content-Type":"application/x-www-form-urlencoded","X-Frappe-CSRF-Token":getCSRF()},
      body:body.toString()
    })
    .then(function(res){ return res.json(); })
    .then(function(j){
      if(j.message&&j.message.ok){ if(tr)tr.classList.remove("saving"); }
      else { toast("Save failed for "+r.inv,1); if(tr)tr.classList.remove("saving"); }
    })
    .catch(function(e){ toast("Save failed for "+r.inv,1); if(tr)tr.classList.remove("saving"); void 0; });
  }

  function validateAll(){
    var d=filtered(); var bad=0;
    for(var j=0;j<d.length;j++){
      var r=d[j]; var e=!!validationError(r);
      if(r.st==="PENDING")e=true;
      if((r.st==="COLLECTED"||r.st==="PARTIAL")&&(!r.colAmt||!r.colDate||!r.mode))e=true;
      if((r.st==="PARTIAL"||r.st==="COMMITTED")&&(!r.cmtAmt||!r.cmtDate))e=true;
      if(r.st==="NOTCOLL"&&(!r.reason||words(r.remark).length<3))e=true;
      if(r.st==="DISPUTE"&&words(r.remark).length<3)e=true;
      if(e){ bad++; var tr=document.querySelector("#tb tr[data-i=\""+r.inv+"\"]"); if(tr)tr.classList.add("err"); }
    }
    toast(bad?bad+" row(s) still incomplete across all pages.":"All "+d.length+" rows are complete.");
  }

  function csvEsc(v){ v=String(v==null?"":v); return /[",\n]/.test(v)?"\""+v.replace(/"/g,"\"\"")+"\"":v; }
  function exportCSV(){
    var d=filtered();
    var head=["S.No","Branch","Client Name","Mobile","Booked By","Practitioner","Invoice No","Invoice Date",
     "Service","Invoice Amount","Paid Amount","Due Amount","Next Due Date","Days Overdue","Manager Status",
     "Collected Now","Collected On","Mode","Will Collect","By Date","Reason","Manager Remark"];
    var lines=[head.join(",")];
    for(var i=0;i<d.length;i++){
      var r=d[i];
      var st=""; for(var k=0;k<STATUS.length;k++){ if(STATUS[k].v===r.st){ st=STATUS[k].t; break; } }
      lines.push([r.sno,r.branch,r.client,maskMobile(r.mobile),r.emp,r.practitioner,r.inv,r.invDate,r.service,
        r.invAmt,r.paid,r.due,r.nextDue,r.age,st,
        r.colAmt,r.colDate,r.mode,r.cmtAmt,r.cmtDate,r.reason,r.remark].map(csvEsc).join(","));
    }
    var blob=new Blob(["\uFEFF"+lines.join("\n")],{type:"text/csv;charset=utf-8"});
    var a=document.createElement("a"); a.href=URL.createObjectURL(blob);
    a.download="LIFE_Pending_Dues_"+(activeBranch()||"ALL")+"_"+new Date().toISOString().slice(0,10)+".csv";
    document.body.appendChild(a); a.click();
    setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); },400);
    toast("Excel file downloaded (mobile numbers masked).");
  }

