  function validDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;var d=new Date(v+"T00:00:00");return !isNaN(d.getTime())&&d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")===v;}
  function validationError(r){
    var c=moneyNumber(r.colAmt),m=moneyNumber(r.cmtAmt),f=FIELDS[r.st];
    if(!f)return "Select a valid status";
    if(c<0||m<0||c>r.due||m>r.due||c+m>r.due+.01)return "Collection plus promise cannot exceed the ERP due";
    if(f.col&&(!(c>0)||!r.mode||MODES.indexOf(r.mode)<0))return "Collected amount and payment mode are required";
    if(f.col&&(!validDate(r.colDate)||r.colDate!==todayISO()))return "Collected date must be today";
    if(f.cmt&&(!(m>0)||!validDate(r.cmtDate)||r.cmtDate<todayISO()))return "Positive promise amount and today/future promise date are required";
    if(r.st==="COLLECTED"&&Math.abs(c-r.due)>.01)return "Full collection must equal the ERP due";
    if(r.st==="NOTCOLL"&&(REASONS.indexOf(r.reason)<0||words(r.remark).length<3))return "Reason and at least 3 remark words are required";
    if(r.st==="DISPUTE"&&words(r.remark).length<3)return "Dispute requires at least 3 remark words";
    if(words(r.remark).length>25)return "Remark limit is 25 words";
    return "";
  }
